CREATE TABLE IF NOT EXISTS capital_reservations (reservation_id BIGSERIAL PRIMARY KEY, decision_id TEXT NOT NULL, order_id TEXT, client_order_id TEXT NOT NULL UNIQUE, requested_capital DOUBLE PRECISION NOT NULL CHECK(requested_capital >= 0), filled_capital DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(filled_capital >= 0), fee_reserve DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(fee_reserve >= 0), state TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), released_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_capital_reservations_active ON capital_reservations(state) WHERE state NOT IN ('released','settled');
CREATE TABLE IF NOT EXISTS reconciliation_leases (order_id TEXT PRIMARY KEY, lease_owner TEXT NOT NULL, lease_expires_at TIMESTAMPTZ NOT NULL, attempt_count INTEGER NOT NULL DEFAULT 0, last_error TEXT, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS risk_snapshots (id BIGSERIAL PRIMARY KEY, available_capital DOUBLE PRECISION, reserved_capital DOUBLE PRECISION, submitted_capital DOUBLE PRECISION, filled_capital DOUBLE PRECISION, uncertain_capital DOUBLE PRECISION, internal_heat DOUBLE PRECISION, venue_collateral DOUBLE PRECISION, mismatch DOUBLE PRECISION, blocked BOOLEAN NOT NULL, reason TEXT, observed_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_risk_snapshots_observed ON risk_snapshots(observed_at DESC);
